Rule 'FND-REL-005' -Tag @{ ruleSet = 'foundry-rules'; group = 'REL'; evaluation = 'static-ps'; status = 'evaluated-subset'; catalogueStatus = 'verified' } -Type 'Microsoft.Search/searchServices' -If { $TargetObject.sku.name -notin 'free', 'serverless' -and $TargetObject.properties.partitionCount -isnot [string] -and $TargetObject.properties.replicaCount -isnot [string] } {
